INSERT INTO "periodical_series" ("series_id", "source_id", "title", "publisher", "region_id", "listing_urls", "license", "agreement_note") VALUES
('tatsugo_koho', 'tatsugo_koho_amami', '広報たつごう', '龍郷町', 'jp-46', '["https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/idx-kohoshi.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2020.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2021.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2022.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2023.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2024.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2025.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/koho2026.html", "https://www.town.tatsugo.lg.jp/kikakukanko/chose/koho-kocho/kohotatsugo.html"]', '掲載内容の著作権は原則として龍郷町に帰属する（町「著作権・リンク」ページ）。私的利用と著作権法上の引用を超える複製・転用には事前の相談が要る旨の記載がある。2026-11-24、オーナーが龍郷町の広報担当と話し、ネットで公開されているものを試験的に利用することを確認した（公開分のみ。取り下げの依頼があれば号・記事を外す）。', '2026-11-24 オーナーが広報担当と確認。テストとして公開分を利用。取り下げの依頼があれば号・記事を外す。');
